<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);require dirname(__DIR__).'/src/bootstrap.php';
try{
 $store=new Annam\Store(new Annam\Database());Annam\Schema::ensure($store->db);$apply=in_array('--apply',$argv,true);$path=ANNAM_ROOT.'/resources/meal-delivery-zones.csv';$localities=ANNAM_ROOT.'/resources/meal-localities.json';$overridesPath=ANNAM_ROOT.'/resources/meal-area-overrides.json';$digest=hash('sha256',file_get_contents($path).file_get_contents($localities).file_get_contents($overridesPath));$version='meal-zones-approved-2026-10-22-v2';$names=array_column(json_decode(file_get_contents($localities),true,64,JSON_THROW_ON_ERROR)['localities'],'area_name','pincode');$overrides=json_decode(file_get_contents($overridesPath),true,64,JSON_THROW_ON_ERROR)['areas'];$result=[];
 try{$store->db->transaction(function()use($store,$apply,$path,$digest,$version,$names,$overrides,&$result){$store->lock();$old=$store->db->one('SELECT digest FROM catalog_catalogsyncrun WHERE tenant_id=? AND version=?',[$store->id(),$version]);if($old){if($old['digest']!==$digest)throw new RuntimeException('Applied zone import was changed.');$result=['already_applied'=>true];return;}
 $file=fopen($path,'rb');$header=false;while(($row=fgetcsv($file))!==false){if(($row[0]??'')==='Pincode'){$header=true;continue;}if(!$header||!preg_match('/^[1-9][0-9]{5}$/D',$row[0]??''))continue;[$pin,$area]=$row;$area=trim($area);if(in_array($area,['','—','Delivery area'],true))$area=$names[$pin]??throw new RuntimeException('Unverified area name for '.$pin);$meals=[];foreach(['breakfast','lunch','dinner','snacks'] as $n=>$key)if(strtolower(trim($row[$n+2]))==='yes')$meals[]=$key;$amount=fn($value)=>str_replace(['₹',',',' '],'',$value);
 $choices=$overrides[$pin]??[['area_name'=>$area,'delivery_fee'=>$amount($row[6])]];
 foreach($choices as $choice){$values=['area_name'=>$choice['area_name'],'pincode'=>$pin,'delivery_fee'=>$choice['delivery_fee'],'min_order'=>$amount($row[7]),'slot_keys'=>$meals,'active'=>strtolower(trim($row[8]))==='yes'?'1':''];$matches=$store->db->rows('SELECT id,area_name FROM delivery_deliveryzone WHERE tenant_id=? AND pincode=?',[$store->id(),$pin]);$id=null;foreach($matches as $m)if($m['area_name']===$values['area_name'])$id=(int)$m['id'];
 if(!$id&&count($matches)===1&&(!isset($overrides[$pin])||in_array($matches[0]['area_name'],['','Delivery area',$names[$pin]??''],true)))$id=(int)$matches[0]['id'];
 (new Annam\Resources($store))->save('zones',$id,$values);$result[]=['pincode'=>$pin,'area'=>$values['area_name'],'fee'=>$values['delivery_fee'],'minimum'=>$values['min_order'],'meals'=>$meals];}
 if(isset($overrides[$pin]))$store->db->rows("UPDATE delivery_deliveryzone SET active=FALSE WHERE tenant_id=? AND pincode=? AND area_name IN ('','Delivery area',?)",[$store->id(),$pin,$names[$pin]??'']);
 }fclose($file);if(!$apply)throw new LogicException('dry-run rollback');$store->db->rows('INSERT INTO catalog_catalogsyncrun(tenant_id,version,digest,report,applied_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP)',[$store->id(),$version,$digest,json_encode($result)]);});}catch(LogicException $e){if($e->getMessage()!=='dry-run rollback')throw $e;}echo json_encode(['applied'=>$apply,'zones'=>$result],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;
}catch(Throwable $e){fwrite(STDERR,'Zone import refused: '.$e->getMessage().PHP_EOL);exit(1);}
